from django.db import migrations, models

AVAILABILITY = [('off', 'Off: stop selling now'), ('auto', 'Auto: follow inventory'), ('always', 'Always: sell past zero')]


def to_modes(apps, schema_editor):
    """
    force_in_stock dishes become "always". A component that was out of stock while it still had inventory had
    been switched off by hand, so it becomes "off" (and blocks its dishes). Everything else follows inventory.
    """
    Dish = apps.get_model("pos_server", "Dish")
    Component = apps.get_model("pos_server", "Component")
    DishComponent = apps.get_model("pos_server", "DishComponent")
    Dish.objects.filter(force_in_stock=True).update(availability="always")
    Component.objects.filter(in_stock=False, inventory__gt=0).exclude(crafting_option="auto").update(availability="off")
    off = DishComponent.objects.filter(component__availability="off").values_list("dish_id", flat=True)
    Dish.objects.filter(pk__in=off).update(blocked=True, in_stock=False)


def to_forced(apps, schema_editor):
    Dish = apps.get_model("pos_server", "Dish")
    Component = apps.get_model("pos_server", "Component")
    Dish.objects.filter(availability="always").update(force_in_stock=True)
    Component.objects.filter(availability="off").update(in_stock=False)


